const data = $input.first().json;

// ---------- helpers ----------

function formatPrice(price) {
    if (price >= 1000) return `$${price.toLocaleString()}`;
    if (price >= 1) return `$${price.toFixed(2)}`;
    return `$${price.toFixed(4)}`;
}

function formatPercent(value) {
    const emoji = value >= 0 ? "🟢" : "🔴";
    const sign = value >= 0 ? "+" : "";
    return `${emoji} ${sign}${value.toFixed(2)}%`;
}

function formatMarketCap(value) {
    if (value >= 1e12) {
        return `$${(value / 1e12).toFixed(2)}T`;
    }

    if (value >= 1e9) {
        return `$${(value / 1e9).toFixed(2)}B`;
    }

    if (value >= 1e6) {
        return `$${(value / 1e6).toFixed(2)}M`;
    }

    return `$${value.toLocaleString()}`;
}

function coinBlock(name, coin) {
    return `💰 *${name}*
${formatPrice(coin.price)}
${formatPercent(coin.change)}
`;
}

function moverBlock(title, list, emoji) {
    let text = `${title}\n`;

    list.forEach(c => {
        text += `${emoji} *${c.symbol}*\n`;
        text += `${formatPrice(c.price)}\n`;
        text += `${c.change >= 0 ? "+" : ""}${c.change.toFixed(2)}%\n\n`;
    });

    return text;
}

// ---------- message ----------

let message = `🌙 *EVENING CRYPTO DIGEST*

Good evening! 👋

Here's today's crypto market summary.

━━━━━━━━━━━━━━━

`;

message += coinBlock("BTC", data.btc);
message += coinBlock("ETH", data.eth);
message += coinBlock("SOL", data.sol);

message += `━━━━━━━━━━━━━━━

🌍 *Market Overview*

💎 Total Market Cap
*${formatMarketCap(data.totalMarketCap)}*

📈 24h Market Change
${formatPercent(data.marketCapChange)}

₿ Bitcoin Dominance
*${data.btcDominance.toFixed(2)}%*

━━━━━━━━━━━━━━━

`;

message += moverBlock("🚀 Top Gainers", data.gainers, "🟢");

message += "━━━━━━━━━━━━━━━\n\n";

message += moverBlock("📉 Top Losers", data.losers, "🔴");

message += "━━━━━━━━━━━━━━━\n\n";

message += "Have a great evening! 🌙";

return [
{
    json: {
        messageText: message
    }
}
];

const message =
    $("📝 Create Evening Message").first().json.messageText;


return $input.all()
.filter(item => String(item.json.user_id || "").trim() !== "")
.map(item => ({
    json: {
        row_number: item.json.row_number,
        user_id: item.json.user_id,
        messageText: message
    }
}));

const data = $input.first().json;

return [
  {
    json: {
      btc: {
        price: data.bitcoin.usd,
        change: data.bitcoin.usd_24h_change,
      },

      eth: {
        price: data.ethereum.usd,
        change: data.ethereum.usd_24h_change,
      },

      sol: {
        price: data.solana.usd,
        change: data.solana.usd_24h_change,
      },
    },
  },
];

const coins = $input.all().map(item => item.json);

const sorted = coins.sort(
  (a, b) => (b.price_change_percentage_24h ?? 0) - (a.price_change_percentage_24h ?? 0)
);

const gainers = sorted.slice(0, 3).map(coin => ({
  symbol: coin.symbol.toUpperCase(),
  price: coin.current_price,
  change: coin.price_change_percentage_24h
}));

const losers = [...sorted]
  .reverse()
  .slice(0, 3)
  .map(coin => ({
    symbol: coin.symbol.toUpperCase(),
    price: coin.current_price,
    change: coin.price_change_percentage_24h
  }));

return [{
  json: {
    gainers,
    losers
  }
}];
